                    args.append(getattr(plugin, arg))
                else:
                    args.append(arg)

            kwargs = {}
            for k,v in self.kwargs.items():
                if isinstance(v, str) and hasattr(plugin, v):
                    kwargs[k] = getattr(plugin, v)
                else:
                    kwargs[k] = v

            value = super().fetch(plugin)
            value = self.func(value, *args, **kwargs)
            return value

