def cleanup(self, wait_for):
        print(f"{self.__class__.__name__} terminated. Waiting for {len(wait_for)} pending futures.")
        for savers in self.sub_savers.values():
            for s in savers:
                s.close(wait_for=wait_for)
        super().cleanup(wait_for)

