def _get_hitlets_data(hitlets, records, to_pe):
    rranges = _touching_windows(
        records["time"], strax.endtime(records), hitlets["time"], strax.endtime(hitlets)
    )

    for i, h in enumerate(hitlets):
        recorded_samples_offset = 0
        n_recorded_samples = 0
        is_first_record = True
        for ind, r_ind in enumerate(range(rranges[i][0], rranges[i][1])):
            r = records[r_ind]
            if r["channel"] != h["channel"]:
                continue

            (r_start, r_end), (h_start, h_end) = strax.overlap_indices(
                r["time"] // r["dt"], r["length"], h["time"] // h["dt"], h["length"]
            )

            if (r_end - r_start) == 0 and (h_end - h_start) == 0:
                # _touching_windows will give a range of overlapping records with hitlet
                # independent of channel. Hence, in rare cases it might be that a record of
                # channel A touches with a hitlet of channel B which starts before the previous
                # record of channel b. Hence we get one non-overlapping record in channel b.
                continue

File: strax/processing/peak_merging.py
Function: _add_lone_hits

def _add_lone_hits(
    peaks, lone_hits, to_pe, n_top_channels=0, store_data_top=False, store_data_start=False
):
    """The core function of add_lone_hits."""
    fully_contained_index = _fully_contained_in(lone_hits, peaks)

    for fc_i, lh_i in zip(fully_contained_index, lone_hits):
        if fc_i == -1:
            continue
        p = peaks[fc_i]
        lh_area = lh_i["area"] * to_pe[lh_i["channel"]]
        p["area"] += lh_area
        p["area_per_channel"][lh_i["channel"]] += lh_area

        # Add lone hit as delta pulse to waveform:
        index = (lh_i["time"] - p["time"]) // p["dt"]
        if index < 0 or index > len(p["data"]):
            raise ValueError("Hit outside of full containment!")
        p["data"][index] += lh_area

        if store_data_top:
            if lh_i["channel"] < n_top_channels:
                p["data_top"][index] += lh_area

        if store_data_start:
            # Non-downsampled waveforms have a fixed minimum dt
            index_wf_start = (lh_i["time"] - p["time"]) // 10

            if index_wf_start < 0:
                raise ValueError("Hit outside of full containment!")

            if index_wf_start < len(p["data_start"]):
                p["data_start"][index_wf_start] += lh_area

