def open_resource(file_name: str, fmt="text"):
    """Open file.

    :param file_name: str, file to open
    :param fmt: format of the file
    :return: opened file

    """
    cached_name = _cache_name(file_name, fmt)
    if cached_name in _resource_cache:
        # Retrieve from in-memory cache
        return _resource_cache[cached_name]
    # File resource
    if fmt in ["npy", "npy_pickle", "npz", "npz_pickle"]:
        result = np.load(file_name, allow_pickle="pickle" in fmt)
        if isinstance(result, np.lib.npyio.NpzFile):
            # Slurp the arrays in the file, so the result can be copied,
            # then close the file so its descriptors does not leak.
            result_slurped = {}
            for k, v in result.items():
                if v.shape:
                    # if numpy array, slurp it
                    result_slurped[k] = v[:]
                else:
                    # if scalar, convert it to a python scalar
                    result_slurped[k] = v.item()
            result.close()
            result = result_slurped
    elif fmt == "pkl":
        with open(file_name, "rb") as f:
            result = pickle.load(f)  # nosec
    elif fmt == "pkl.gz":
        with gzip.open(file_name, "rb") as f:
            result = pickle.load(f)  # nosec
    elif fmt == "dill":
        with open(file_name, "rb") as f:
            result = dill.load(f)  # nosec
    elif fmt == "dill.gz":
        with gzip.open(file_name, "rb") as f:
            result = dill.load(f)  # nosec
    elif fmt == "json.gz":
        with gzip.open(file_name, "rb") as f:
            result = json.load(f)
    elif fmt == "json":
        with open(file_name, mode="r") as f:
            result = commentjson.load(f)
    elif fmt == "binary":
        with open(file_name, mode="rb") as f:
            result = f.read()
    elif fmt in ["text", "txt"]:
        with open(file_name, mode="r") as f:
            result = f.read()
    elif fmt == "csv":
        result = pd.read_csv(file_name)
    else:
        raise ValueError(f"Unsupported format {fmt}!")

    # Store in in-memory cache
    _resource_cache[cached_name] = result

    return result

