def _create_widgets(
        self,
        x_field="cs1",
        y_field="cs2",
        _index_slider=None,
    ):
        """Creates widgets for the x and y field as well as an slider for the event index if not
        supplied externally."""
        fields = list(self.events.dtype.names)
        if self.exclude_fields:
            if hasattr(self.exclude_fields, "__call__"):
                fields = self.exclude_fields(fields)
            elif isinstance(self.exclude_fields, (list, tuple)):
                fields = self._exclude_fields(fields, self.exclude_fields)
            else:
                raise ValueError('"exclude_fields" must be either a list or a function!')

        fields.sort()
        self.x_field_widget = pn.widgets.Select(value=x_field, options=fields, name="X-field")

        self.y_field_widget = pn.widgets.Select(value=y_field, options=fields, name="Y-field")

        if not _index_slider:
            self.index_slider = pn.widgets.IntSlider(
                start=0, end=len(self.events), name="Event Index:"
            )
        else:
            self.index_slider = _index_slider

