def compute(self, raw_records_nv, start, end)

        if not len(raw_records_nv):
            rr = raw_records_nv
            lrs = np.zeros(0, dtype=self.dtype["lone_raw_record_statistics_nv"])
            return {
                "raw_records_coin_nv": rr,
                "lone_raw_record_statistics_nv": lrs,
