def to_dict_tuple(res: dict):
    """Convert list configs to tuple configs."""
    res = res.copy()
    for k, v in res.copy().items():
        if isinstance(v, list):
            # Remove lists to tuples
            res[k] = tuple(_v if not isinstance(_v, list) else tuple(_v) for _v in v)
    return res

