def _data_query(self, key):
        """Return MongoDB query for data field matching key."""
        return {
            "data": {
                "$elemMatch": {
                    "type": key.data_type,
                    "$and": [
                        {
                            "$or": [
                                {"meta.lineage": key.lineage},
                                {
                                    "did": {"$regex": f"/*{key.data_type}-{key.lineage_hash}"},
                                },
                            ]
                        },
                        {"$or": self.available_query},
                    ],
                }
            }
        }

