def run_id_to_time(self, run_id):
        doc = self.run_doc(run_id)
        start = doc["start"]
        end = doc.get("end", None)

        # Run still ongoing
        if end is None:
            time = start
        else:
            time = start + (end - start) / 2

        return self.clock.normalize_tz(time)

