def _min(self, fields=None, **labels) -> Any:
        if fields is None:
            fields = list(self.schema.__fields__)
        elif isinstance(fields, str):
            fields = [fields]

        labels = {k: v for k, v in labels.items() if v is not None}
        query = self.schema.compile_query(self.storage, **labels)

