                "you can ignore this."
            )
        except OperationFailure as e:
            if e.code == 13: # Unauthorized
                warnings.warn(
                    "Your account does not have permissions to create indexes on this database. "
                    "Assuming indexes are already managed by an administrator."
                )
            else:
                raise e

